const incoming = $input.first().json.body;
let payload;
try {
  payload = typeof incoming === 'string' ? JSON.parse(incoming) : incoming;
} catch {
  throw new Error('El cuerpo recibido no es JSON válido');
}
if (!payload || payload.source !== 'taskflow' || !payload.task?.id || !payload.task?.title) {
  throw new Error('Solicitud inválida: faltan source, task.id o task.title');
}
const task = payload.task;
const now = new Date();
const due = task.dueDate ? new Date(task.dueDate + 'T23:59:59') : null;
const hasValidDueDate = Boolean(due && !Number.isNaN(due.getTime()));
const days = hasValidDueDate ? Math.ceil((due.getTime() - now.getTime()) / 86400000) : null;
let score = task.status === 'in_progress' ? 25 : task.status === 'completed' ? 0 : 10;
const reasons = [];
if (days !== null) {
  if (days < 0) { score += 75; reasons.push('La fecha límite ya pasó'); }
  else if (days === 0) { score += 65; reasons.push('Vence hoy'); }
  else if (days <= 2) { score += 50; reasons.push('Vence dentro de 48 horas'); }
  else if (days <= 7) { score += 25; reasons.push('Vence esta semana'); }
} else { reasons.push('No tiene una fecha límite válida'); }
if (task.status === 'in_progress') reasons.push('Ya está en progreso');
if (task.status === 'completed') reasons.push('La tarea ya está completada');
score = Math.max(0, Math.min(100, score));
const priority = score >= 85 ? 'critical' : score >= 60 ? 'high' : score >= 35 ? 'medium' : 'low';
const nextSteps = [
  days !== null && days < 0 ? 'Reprogramar o resolver el vencimiento hoy' : days !== null && days <= 2 ? 'Reservar un bloque de trabajo hoy' : 'Definir el siguiente paso concreto',
  task.description ? 'Dividir la tarea en una acción de menos de 30 minutos' : 'Agregar contexto y criterio de finalización',
  'Actualizar el estado después del próximo avance'
];
return [{json:{priority,score,summary:task.title + ': prioridad ' + priority,reason:reasons.join('. '),nextSteps,notified:score>=60,processedAt:new Date().toISOString(),taskId:task.id}}];
